#!/bin/bash  # Configuración de IP local y puerto HOST="192.168.1.145"     # Dirección IP de tu servidor PORT="8000"              # Puerto que usas para Laravel  # Verificar si el puerto ya está en uso if lsof -i :$PORT > /dev/null; then     echo "El puerto $PORT ya está en uso. Deteniendo el servidor..."     # Detén el proceso que está usando el puerto, si es necesario     kill $(lsof -t -i:$PORT) else     echo "El puerto $PORT está libre. Iniciando servidor Laravel..." fi  # Inicia el servidor Laravel php artisan serve --host=$HOST --port=$PORT & echo "Servidor Laravel corriendo en http://$HOST:$PORT"  # Configura túnel SSH # Reemplaza usuario@servidor_remoto con tus datos de servidor REMOTE_SERVER="usuario@servidor_remoto" REMOTE_PORT=22  # Puerto SSH por defecto, cámbialo si es necesario  # Crea el túnel SSH echo "Estableciendo túnel SSH..." ssh -f -N -L $PORT:$HOST:$PORT $REMOTE_SERVER -p $REMOTE_PORT  # Informa al usuario echo "Túnel SSH creado. Ahora puedes acceder al sistema desde: http://localhost:$PORT"
